const TZ = 'America/Toronto';

function today() {
  const p = new Intl.DateTimeFormat('en-CA', {
    timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit'
  }).formatToParts(new Date());
  const g = t => +p.find(x => x.type === t).value;
  return { y: g('year'), m: g('month'), d: g('day') };
}

function addMonth(dt) {
  const t = dt.m;
  const y = dt.y + Math.floor(t / 12);
  const m = t % 12 + 1;
  const last = new Date(Date.UTC(y, m, 0)).getUTCDate();
  return { y, m, d: Math.min(dt.d, last) };
}

function parse(s) {
  const d = new Date(String(s).trim() + ' UTC');
  if (isNaN(d)) throw new Error('Fecha inválida: ' + s);
  return { y: d.getUTCFullYear(), m: d.getUTCMonth() + 1, d: d.getUTCDate() };
}

const pay = parse("{{nextPay}}");
const exp = addMonth(today());

return exp.y === pay.y && exp.m === pay.m && exp.d === pay.d;
